const fs = require('fs');
const readline = require('readline');

const API_KEY = 'lT1DAmOteO7rCM3b6QjlGkXzFhN9jGeB';
const TYPESENSE_URL = 'http://127.0.0.1:8108';

async function run() {
  try {
    // 1. Delete collection if exists
    console.log('Deleting products collection if exists...');
    try {
      await fetch(`${TYPESENSE_URL}/collections/products`, {
        method: 'DELETE',
        headers: { 'X-TYPESENSE-API-KEY': API_KEY }
      });
    } catch (e) {
      // Ignore
    }

    // 2. Create collection
    console.log('Creating products collection...');
    const schema = {
      name: 'products',
      fields: [
        { name: 'id', type: 'string' },
        { name: 'name', type: 'string' },
        { name: 'category', type: 'string', facet: true },
        { name: 'brand', type: 'string', facet: true },
        { name: 'price', type: 'float', facet: true },
        { name: 'rating', type: 'float', facet: true },
        { name: 'tags', type: 'string[]', facet: true }
      ]
    };

    const res = await fetch(`${TYPESENSE_URL}/collections`, {
      method: 'POST',
      headers: {
        'X-TYPESENSE-API-KEY': API_KEY,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(schema)
    });

    if (!res.ok) {
      const errText = await res.text();
      throw new Error(`Failed to create collection: ${res.statusText} - ${errText}`);
    }
    console.log('Collection created successfully!');

    // 3. Read products.jsonl and index them
    console.log('Indexing products...');
    const fileStream = fs.createReadStream('/home/user/filterchip/data/products.jsonl');
    const rl = readline.createInterface({
      input: fileStream,
      crlfDelay: Infinity
    });

    const docs = [];
    for await (const line of rl) {
      if (line.trim()) {
        docs.push(JSON.parse(line));
      }
    }

    console.log(`Found ${docs.length} documents to index.`);

    // Typesense import endpoint accepts JSONL
    const jsonlData = docs.map(d => JSON.stringify(d)).join('\n');
    const importRes = await fetch(`${TYPESENSE_URL}/collections/products/documents/import?action=create`, {
      method: 'POST',
      headers: {
        'X-TYPESENSE-API-KEY': API_KEY,
        'Content-Type': 'text/plain'
      },
      body: jsonlData
    });

    const importText = await importRes.text();
    console.log('Import response:', importText);

  } catch (error) {
    console.error('Error:', error);
  }
}

run();

